import numpy as np
coords=[ [7], [6,12],[5,11],[4,10],[3,9],[2,8,13],[1,7,12],[11],[],[],[],[3],[2,6],[1,5],[0,4,8],[3,7] ]
a=np.zeros((16,16),int)
for r,cs in enumerate(coords):
 for c in cs:a[r,c]=4
# 4conn background components, mark reach border
from collections import deque
seen=np.zeros_like(a,bool)
comps=[]
for r in range(16):
 for c in range(16):
  if a[r,c] or seen[r,c]: continue
  q=deque([(r,c)]); seen[r,c]=1; cells=[]; border=False
  while q:
   x,y=q.popleft();cells.append((x,y));border |= x in (0,15) or y in (0,15)
   for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
    nx,ny=x+dx,y+dy
    if 0<=nx<16 and 0<=ny<16 and not a[nx,ny] and not seen[nx,ny]: seen[nx,ny]=1;q.append((nx,ny))
  comps.append((len(cells),border,cells))
[(n,b,cells[:10]) for n,b,cells in comps if not b],sum(n for n,b,_ in comps if not b)

def complement_components(wall,neighbor_mode=8):
 h,w=wall.shape;seen=np.zeros_like(wall,bool);cs=[]
 dirs=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (neighbor_mode==8 or abs(dr)+abs(dc)==1)]
 for r in range(h):
  for c in range(w):
   if wall[r,c] or seen[r,c]:continue
   q=deque([(r,c)]);seen[r,c]=1;cells=[];bord=False
   while q:
    x,y=q.popleft();cells.append((x,y));bord |= x==0 or y==0 or x==h-1 or y==w-1
    for dr,dc in dirs:
     nx,ny=x+dr,y+dc
     if 0<=nx<h and 0<=ny<w and not wall[nx,ny] and not seen[nx,ny]:seen[nx,ny]=1;q.append((nx,ny))
   cs.append((len(cells),bord,cells))
 return cs
cs=complement_components(a==4,8)
[(n,b,cells[:12]) for n,b,cells in cs if not b],sum(n for n,b,cells in cs if not b)

